async()=>{
 const f=document.createElement('iframe');f.src='/child/original';const loaded=new Promise(r=>f.onload=r);document.body.append(f);await loaded;
 const out=[],snap=tag=>out.push({tag,top:location.pathname+location.hash,child:f.contentWindow.location.pathname+f.contentWindow.location.hash,length:history.length,childLength:f.contentWindow.history.length,state:f.contentWindow.history.state});snap('initial');
 f.contentWindow.history.replaceState({n:1},'','replaced');snap('replace');
 f.contentWindow.history.pushState({n:2},'','pushed');snap('push');
 await new Promise(r=>setTimeout(r,100)); f.contentWindow.location.hash='hash';await new Promise(r=>setTimeout(r,100));snap('hash');
 f.contentWindow.history.back();await new Promise(r=>setTimeout(r,100));snap('back');
 history.back();await new Promise(r=>setTimeout(r,100));snap('parent back');
 try{f.contentWindow.history.replaceState({n:9},'','https://example.com')}catch(e){out.push({error:e.name,state:f.contentWindow.history.state})}
 return out;}
